MOTA.Charter = {
  { "note", "Founding Document — Ratified November 2026" },
  { "note", "World of Warcraft: Forever — Alliance" },
  { "part", "Preamble" },
  { "body", "The Ministry of the Allied is a guild founded not merely as an instrument of play, but as a living political community. Its members are citizens, not subjects. Its government is accountable, not appointed. Its history is recorded, not forgotten." },
  { "body", "This Charter is the supreme governing document of the Ministry of the Allied. All laws, elections, appointments, and decisions made within the guild must be consistent with it. Where conflict arises between a law and this Charter, the Charter prevails." },
  { "part", "Part I — The Crown" },
  { "section", "1.1 The Monarchy" },
  { "body", "The Ministry of the Allied is governed under a constitutional monarchy. The Crown is held jointly by two co-monarchs, referred to collectively as the Crown and individually as the King. The Crown is permanent and does not stand for election." },
  { "body", "The Crown represents the continuity, identity, and stability of the guild. Governments rise and fall. The Crown endures." },
  { "section", "1.2 Powers of the Crown" },
  { "body", "The Crown holds the following reserved powers:" },
  { "body", "•  To found, maintain, and dissolve the guild itself" },
  { "body", "•  To dissolve the sitting government and trigger a General Election" },
  { "body", "•  To grant Royal Assent to laws passed by the government" },
  { "body", "•  To veto a law before Royal Assent is given" },
  { "body", "•  To appoint the three members of the High Judiciary" },
  { "body", "•  To sign-off on any sentence of Exile" },
  { "body", "•  To declare a State of Emergency suspending normal government for a period not exceeding fourteen days" },
  { "section", "1.3 Dissolution" },
  { "body", "The Crown may dissolve a sitting government at any time. However, dissolution without the visible support of the wider citizenry carries significant political cost to the Crown's standing and legitimacy. The power exists. Its use is not consequence-free." },
  { "section", "1.4 Succession and Transition" },
  { "body", "The two co-monarchs may hold formal ceremonial transitions of ruling authority between themselves at intervals of their choosing. These transitions are civic events and matters of public record." },
  { "section", "1.5 The Apolitical Crown" },
  { "body", "The Crown stands above party politics. A monarch may not join, hold office in or fund a political party, and may not campaign for or against one. Monarchs retain their vote in General Elections." },
  { "part", "Part II — The Government" },
  { "section", "2.1 The Prime Minister" },
  { "body", "Executive power within the guild is held by the Prime Minister. The Prime Minister leads the government, sets policy, directs the treasury, and represents the guild in diplomatic matters with other guilds." },
  { "body", "The Prime Minister is elected by direct popular vote of all citizens. The candidate who receives the most votes becomes Prime Minister. In the event of a tie, a second vote is held within 48 hours between the tied candidates only." },
  { "section", "2.2 The Cabinet" },
  { "body", "The Prime Minister appoints their own Cabinet upon taking office. Cabinet ministers hold portfolios relevant to guild operations, which may include but are not limited to:" },
  { "body", "•  Minister of the Treasury — manages the guild bank and taxation" },
  { "body", "•  Minister of War — leads raid organisation and PvP strategy" },
  { "body", "•  Minister of Trade — oversees the guild market and inter-guild commerce" },
  { "body", "•  Minister of Recruitment — manages citizen intake and regional assignment" },
  { "body", "•  Minister of Justice — liaises with the High Judiciary on matters of law enforcement" },
  { "body", "Cabinet ministers serve at the pleasure of the Prime Minister and may be dismissed and replaced at any time." },
  { "section", "2.3 Term Length" },
  { "body", "A government's term lasts three calendar months from the date the Prime Minister takes office. At the end of each term, a General Election is held." },
  { "section", "2.4 The Opposition" },
  { "body", "The party that loses a General Election forms the Official Opposition. The leader of the losing party holds the title of Leader of the Opposition and is a recognised office within the guild. The Opposition's role is to scrutinise the government, challenge its decisions publicly, and present an alternative programme for the next election." },
  { "part", "Part III — Elections" },
  { "section", "3.1 The Two-Party System" },
  { "body", "Political life in the Ministry of the Allied is organised around two registered parties. Each party holds a founding ideology and a set of positions on guild policy. Parties must be formally registered with the Crown before fielding candidates." },
  { "section", "3.2 Party Membership" },
  { "body", "Each registered party operates its own membership system, independent of guild citizenship. Party membership is voluntary and open to any citizen in good standing." },
  { "body", "To become a party member, a citizen pays a minimum donation of 50 silver into the guild bank, recorded against their chosen party. Members may donate any amount above this floor. Each party's donations and spending are held as a separate account and published on the public ledger as they occur." },
  { "body", "Party funds are released only at the request of that party's leader, and are paid out by the Crown. Taking or using party funds without that authority is an offence." },
  { "body", "Party members elect their own party leader through an internal vote. That leader is the candidate who stands for Prime Minister in the General Election. Citizens who are not party members do not participate in internal leadership elections but retain their full vote in the General Election." },
  { "body", "The leadership ballot is open: once the count has been ratified by the Crown, how each member voted is published to the whole guild. A tie goes to a run-off within 48 hours between the tied candidates; a second tie is settled by the Crown by a public roll of the dice." },
  { "body", "Each party leader names a Deputy Leader. This is the leader's own decision. If the leader leaves office, the Deputy becomes leader without a vote." },
  { "body", "Campaign funding — parties may use their membership donations freely during the campaign period to advance their electoral prospects. This includes gifting elixirs, consumables, or other items to citizens to court their vote. Campaign spending is a matter of political competition, not regulation. Citizens are free to accept gifts and vote however they choose." },
  { "body", "Party membership donations are separate from guild treasury taxation and do not count toward any treasury contribution requirement for candidacy." },
  { "section", "3.3 General Elections" },
  { "body", "A General Election is held at the end of every three-month term, or earlier in the event of a Snap Election. The election period runs as follows:" },
  { "body", "•  Weeks 1–2 of election period: Campaign period. Candidates may make their case publicly." },
  { "body", "•  Week 2: Formal debate. A moderated debate is held between the two candidates, open to all citizens to observe and submit questions." },
  { "body", "•  End of Week 2: Voting opens for 2 hours, at a time declared by the Crown. All citizens cast their vote by direct, secret ballot." },
  { "body", "•  Vote close: Results announced by the Crown. Incoming Prime Minister takes office within 24 hours." },
  { "section", "3.4 Candidacy Requirements" },
  { "body", "To stand as a candidate for Prime Minister, a citizen must meet the requirements in force at the time of the election. Requirements formalise as the guild and server mature:" },
  { "body", "•  Early game: Candidates must be in good standing with the guild, have been a citizen for a minimum of two weeks, and have demonstrated meaningful contribution to the community." },
  { "body", "•  Mid game: Candidates must additionally have led at least two guild raids to completion, or have made a recorded contribution to the guild treasury above the threshold set by law." },
  { "body", "•  Late game (Level 60 era): Candidates must be Level 60, have led at least three successful guild raids, or have made a significant recorded contribution to the guild treasury." },
  { "body", "The Crown reserves the right to rule a candidate ineligible where eligibility is disputed." },
  { "section", "3.5 Snap Elections" },
  { "body", "A Snap Election may be triggered in two ways:" },
  { "body", "•  By dissolution of the government by the Crown" },
  { "body", "•  By a successful Vote of No Confidence" },
  { "body", "A Snap Election follows the same format as a General Election, compressed into a shorter campaign period at the Crown's discretion." },
  { "section", "3.6 Leadership Contests" },
  { "body", "Every General Election includes a leadership contest in each party, opened by the Crown 28 days before polling day and concluded no later than 14 days before it. Snap Elections do not include one. The campaign period is not reset if a leader withdraws." },
  { "body", "If a party has neither leader nor Deputy when a campaign is due to begin or during it, polling day moves back 14 days while that party holds an emergency contest. This may happen only once per election. If the party still has no leader, the election proceeds without it." },
  { "part", "Part IV — Legislation" },
  { "section", "4.1 Laws" },
  { "body", "The government may pass laws governing the conduct and operations of the guild. Laws may cover taxation rates, loot distribution, recruitment criteria, trade conduct, rules of engagement in PvP, and any other matter relevant to guild life." },
  { "body", "All laws require Royal Assent from the Crown before taking effect." },
  { "section", "4.2 Duration" },
  { "body", "All laws last for exactly three months from the date of Royal Assent. They do not carry over automatically between governments. An incoming Prime Minister must actively choose to renew a law within the first two weeks of taking office, or it expires." },
  { "body", "This ensures that no government inherits permanent policy it did not choose. The statute book is always a reflection of current democratic will." },
  { "section", "4.3 The Law Registry" },
  { "body", "All active laws, their dates of passage, their authors, and their expiry dates are recorded in the Law Registry. The Law Registry is a public document maintained by the Minister of Justice and published to the guild repository." },
  { "part", "Part V — The Vote of No Confidence" },
  { "section", "5.1 Mechanism" },
  { "body", "Citizens may trigger a Snap Election through a Vote of No Confidence in the sitting government. To do so:" },
  { "body", "•  Citizens submit their vote of no confidence by in-game mail addressed to the Crown" },
  { "body", "•  Votes must state clearly that they constitute a Vote of No Confidence in the current government" },
  { "body", "•  If the number of submitted votes reaches or exceeds 40% of the active citizen population within a seven-day window, the threshold is met" },
  { "body", "•  Upon threshold being met, the Crown announces the result and triggers a Snap Election" },
  { "section", "5.2 Cooling Period" },
  { "body", "Following a failed Vote of No Confidence — one that does not reach the threshold — a cooling period of thirty days must pass before another can be initiated. This prevents the mechanism from becoming a tool of persistent harassment." },
  { "section", "5.3 Active Citizen Population" },
  { "body", "For the purposes of calculating the threshold, the active citizen population is defined as all citizens who have logged in within the preceding thirty days. The Crown maintains this count and publishes it at the start of each month." },
  { "part", "Part VI — The High Judiciary" },
  { "section", "6.1 Composition" },
  { "body", "The High Judiciary consists of three Justices appointed by the Crown. Justices may not hold any other office within the guild during their appointment. They serve for the duration of two full terms and may be reappointed once." },
  { "section", "6.2 Role" },
  { "body", "The High Judiciary is independent of the government. It is responsible for:" },
  { "body", "•  Hearing and ruling on accusations of law-breaking by citizens" },
  { "body", "•  Ruling on disputes about the interpretation of this Charter or any active law" },
  { "body", "•  Overseeing the punishment process and ensuring proportionality" },
  { "body", "The government may not direct, instruct, or interfere with the High Judiciary." },
  { "section", "6.3 Proceedings" },
  { "body", "Accusations are brought to the High Judiciary by any citizen. The accused is entitled to make a statement in their defence. The Justices deliberate and issue a ruling. All rulings are published to the guild record." },
  { "part", "Part VII — Punishment" },
  { "section", "7.1 The Punishment Ladder" },
  { "body", "Punishments are applied in proportion to the severity of the offence and are ruled on by the High Judiciary. The ladder of available sanctions is as follows:" },
  { "body", "1. Public Censure — A formal recorded statement of wrongdoing. Reputational consequence only. Logged permanently in the guild record." },
  { "body", "2. Treasury Fine — A gold payment to the guild bank. Amount set by the law broken or determined by the Justices." },
  { "body", "3. Trade Embargo — Loss of access to the guild bank, guild market, and resource sharing. The citizen may continue to play and raid but is excluded from economic benefits." },
  { "body", "4. Suspension from Office — Removal from any cabinet or council position pending resolution of the matter." },
  { "body", "5. Exile — Removal from the guild. Requires sign-off from the Crown. This is the severest sanction and is reserved for the gravest offences." },
  { "section", "7.2 Appeal" },
  { "body", "A citizen may appeal a ruling to the Crown within 48 hours of its issue. The Crown's decision on appeal is final." },
  { "part", "Part VIII — Citizenship and Regions" },
  { "section", "8.1 Citizens" },
  { "body", "All guild members are citizens of the Ministry of the Allied and are entitled to vote in General Elections and Votes of No Confidence." },
  { "section", "8.2 Regional Districts" },
  { "body", "Citizens are assigned to one of the guild's regional districts upon joining. Each district is anchored to a location in Stormwind and represents a constituency within the political community." },
  { "body", "Current districts are:" },
  { "body", "District · Stormwind Location · Character" },
  { "body", "The Old Quarter · Old Town · Military, PvP, defence" },
  { "body", "The Arcane Ward · Mage Quarter · Crafting, intellect, strategy" },
  { "body", "The Iron District · Dwarven District · Industry, mining, production" },
  { "body", "The Cathedral Ward · Cathedral Square · Justice, ceremony, diplomacy" },
  { "body", "The Harbour Quarter · Stormwind Harbour · Trade, commerce, external affairs" },
  { "body", "Each district elects a Regional Representative who sits on the Regional Council. The Regional Council is an advisory body to the government and does not hold legislative power, but must be consulted on matters that primarily affect their constituents." },
  { "section", "8.3 The Throne" },
  { "body", "The Crown holds court in Stormwind Keep. It is the seat of the monarchy and the location of formal ceremonies, elections announcements, and matters of state." },
  { "part", "Part IX — Amendments" },
  { "body", "This Charter may be amended by the Crown at any time. Proposed amendments brought by the sitting government or citizenry must receive Crown approval to take effect. All amendments are versioned and dated in the public record." },
  { "note", "The Ministry of the Allied — Stormwind, Azeroth" },
  { "note", "Version 1.1 — November 2026 — Added Part III §3.2 Party Membership" },
  { "note", "Version 1.2 — 6 November 2026 — Part III §3.3: voting window shortened to 2 hours, by secret ballot" },
  { "note", "Version 1.3 — 8 November 2026 — Agreed by both Kings: Part I §1.5 The Apolitical Crown; Part III §3.2 party donations of 50 silver into the guild bank on a public ledger, open leadership ballots, Deputy Leaders; Part III §3.6 Leadership Contests" },
}
